class OpenAPITransport(Protocol):
    def __call__(
        self,
        operation_id: OperationId,
        body: Any = None,
        *,
        path_parameters: dict[str, str] | None = None,
        query: dict[str, Any] | None = None,
        headers: dict[str, str] | None = None,
    ) -> Any: ...


class OpenAPIClient:
    """Generated low-level JSON client; streaming and WebSockets remain custom."""

    def __init__(self, transport: OpenAPITransport):
        self._transport = transport

    def request(
        self,
        operation_id: OperationId,
        body: Any = None,
        *,
        path_parameters: dict[str, str] | None = None,
        query: dict[str, Any] | None = None,
        headers: dict[str, str] | None = None,
    ) -> Any:
        """Execute an ordinary generated operation by stable operation ID."""
        operation = _OPERATION_TABLE[operation_id]
        if operation.streaming_request or operation.websocket:
            raise ValueError(
                f"postgrip-service: operation {operation_id.value!r} requires its protocol adapter"
            )
        return self._transport(
            operation_id,
            body,
            path_parameters=path_parameters,
            query=query,
            headers=headers,
        )

    def adopt_git_hub_repository(self, service_id: str, body: AdoptGitHubRepositoryRequestBody, *, idempotency_key: str, if_match: str) -> AdoptGitHubRepositoryResponseBody:
        _headers: dict[str, str] = {}
        _headers['Idempotency-Key'] = str(idempotency_key)
        _headers['If-Match'] = str(if_match)
        return cast(AdoptGitHubRepositoryResponseBody, self._transport(OperationId.ADOPT_GIT_HUB_REPOSITORY, body, path_parameters={'serviceId': service_id}, headers=_headers))

